"""Client for interacting with qBraid Hub projects (Explore)."""

from __future__ import annotations

import logging
import os
import subprocess
from pathlib import Path
from typing import Any, Callable, Optional

from qbraid_core.client import QbraidClientV1
from qbraid_core.exceptions import RequestsApiError
from qbraid_core.registry import register_client

from .exceptions import (
    ProjectCloneError,
    ProjectInstallError,
    ProjectNotFoundError,
    ProjectServiceRequestError,
)

logger = logging.getLogger(__name__)


def _run_env_preflight(
    emc: Any,
    env_slug: str,
    progress_callback: Optional[Callable[[str, int, str], None]] = None,
) -> tuple[Any, Optional[dict[str, Any]]]:
    """Run pre-flight compatibility checks for a single environment.

    Fetches environment metadata, runs platform/python checks, and reports
    any issues via the progress callback.

    Returns:
        Tuple of (EnvInstallPreflight, env_info_dict_or_None).
    """
    from qbraid_core.services.environments.preflight import (
        EnvInstallPreflight,
        check_env_install_preflight,
    )

    try:
        env_info = emc.get_environment_by_slug(env_slug)
    except Exception:  # noqa: BLE001
        logger.debug("Could not fetch env info for preflight: %s", env_slug)
        return EnvInstallPreflight(), None  # all-clear defaults → proceed with download

    preflight = check_env_install_preflight(env_info)

    # Report issues via progress callback so callers (CLI, SSE) can display them
    for issue in preflight.issues:
        logger.warning("Preflight [%s]: %s", env_slug, issue)
        if progress_callback:
            progress_callback("env", 0, f"Warning ({env_slug}): {issue}")

    return preflight, env_info


def _install_env_with_preflight(
    emc: Any,
    env_slug: str,
    envs_target: str,
    preflight: Any,
    env_info: Optional[dict[str, Any]],
    env_progress: Optional[Callable] = None,
    auto_add_kernels: bool = True,
) -> None:
    """Install a single environment using the preflight result to decide strategy.

    - Already installed → skip
    - Platform mismatch → create similar local environment
    - Python missing + uv available → install python via uv, then download
    - Python missing + no uv → create similar local environment
    - All clear → download from cloud storage

    Raises on failure; returns None on success.
    """
    # Check if already installed
    try:
        from qbraid_core.services.environments.registry import EnvironmentRegistryManager

        registry_mgr = EnvironmentRegistryManager()
        existing = registry_mgr.find_by_slug(env_slug)
        if existing:
            env_id, entry = existing
            if entry.path.exists():
                logger.info(
                    "Environment %s already installed (env_id=%s), skipping", env_slug, env_id
                )
                if env_progress:
                    env_progress("skip", 1, 1)
                return
    except Exception:  # noqa: BLE001
        pass  # Registry not available — proceed with install

    create_local = False

    if not preflight.platform_compatible:
        logger.info(
            "Platform mismatch for %s (%s vs %s) — creating local env",
            env_slug,
            preflight.env_platform,
            preflight.current_platform,
        )
        create_local = True
    elif not preflight.python_available:
        if preflight.uv_available:
            logger.info(
                "Python %s missing for %s — installing via uv",
                preflight.required_python,
                env_slug,
            )
            from qbraid_core.services.environments import install_python

            try:
                install_python(preflight.required_python)
                logger.info("Installed Python %s via uv", preflight.required_python)
            except Exception as err:  # noqa: BLE001
                logger.warning(
                    "Failed to install Python %s: %s — falling back to local env",
                    preflight.required_python,
                    err,
                )
                create_local = True
        else:
            logger.info(
                "Python %s missing for %s, uv not available — creating local env",
                preflight.required_python,
                env_slug,
            )
            create_local = True

    if create_local and env_info is not None:
        emc.create_similar_environment(
            env_info=env_info,
            target_dir=envs_target,
            auto_add_kernels=auto_add_kernels,
            progress_callback=env_progress,
        )
    else:
        # Download from cloud — need asyncio.run for sync callers
        import asyncio

        asyncio.run(
            emc.install_environment_from_storage(
                slug=env_slug,
                target_dir=envs_target,
                progress_callback=env_progress,
                auto_add_kernels=auto_add_kernels,
                auto_install_python=False,  # already handled above
                env_info=env_info,  # skip the internal fetch when caller already has it
            )
        )


async def _install_env_with_preflight_async(
    emc: Any,
    env_slug: str,
    envs_target: str,
    preflight: Any,
    env_info: Optional[dict[str, Any]],
    env_progress: Optional[Callable] = None,
    auto_add_kernels: bool = True,
) -> None:
    """Async version of _install_env_with_preflight for use inside event loops."""
    import asyncio

    # Check if already installed
    try:
        from qbraid_core.services.environments.registry import EnvironmentRegistryManager

        def _check_existing():
            registry_mgr = EnvironmentRegistryManager()
            existing = registry_mgr.find_by_slug(env_slug)
            if existing:
                env_id, entry = existing
                if entry.path.exists():
                    return env_id
            return None

        existing_id = await asyncio.to_thread(_check_existing)
        if existing_id:
            logger.info(
                "Environment %s already installed (env_id=%s), skipping", env_slug, existing_id
            )
            if env_progress:
                env_progress("skip", 1, 1)
            return
    except Exception:  # noqa: BLE001
        pass

    create_local = False

    if not preflight.platform_compatible:
        logger.info(
            "Platform mismatch for %s — creating local env",
            env_slug,
        )
        create_local = True
    elif not preflight.python_available:
        if preflight.uv_available:
            from qbraid_core.services.environments import install_python

            try:
                await asyncio.to_thread(install_python, preflight.required_python)
                logger.info("Installed Python %s via uv", preflight.required_python)
            except Exception as err:  # noqa: BLE001
                logger.warning(
                    "Failed to install Python %s: %s — falling back to local env",
                    preflight.required_python,
                    err,
                )
                create_local = True
        else:
            create_local = True

    if create_local and env_info is not None:
        await asyncio.to_thread(
            emc.create_similar_environment,
            env_info=env_info,
            target_dir=envs_target,
            auto_add_kernels=auto_add_kernels,
            progress_callback=env_progress,
        )
    else:
        await emc.install_environment_from_storage(
            slug=env_slug,
            target_dir=envs_target,
            progress_callback=env_progress,
            auto_add_kernels=auto_add_kernels,
            auto_install_python=False,
            env_info=env_info,  # skip the internal fetch when caller already has it
        )


def _extract_data(response: Any) -> Any:
    """Handle both {success, data} and bare API response formats."""
    if isinstance(response, dict) and response.get("success") and "data" in response:
        return response["data"]
    return response


@register_client()
class ProjectsClient(QbraidClientV1):
    """Client for interacting with qBraid Hub projects (Explore page).

    Hub projects are GitHub-hosted templates with optional pre-configured
    environments. Users can clone them and install the associated environment
    in a single operation.

    Example:
        >>> from qbraid_core.services.projects import ProjectsClient
        >>> client = ProjectsClient()
        >>> projects = client.list_projects()
        >>> for p in projects:
        ...     print(p["title"], p["slug"])
        >>> client.install_project("qiskit-tutorial", target_dir="~/")
    """

    def list_projects(
        self,
        search: Optional[str] = None,
        featured: Optional[bool] = None,
        category: Optional[str] = None,
        visibility: Optional[str] = None,
    ) -> list[dict[str, Any]]:
        """List all hub projects.

        Args:
            search: Search query across title and description
            featured: Filter for featured projects only
            category: Project category filter
            visibility: 'public' or 'private'

        Returns:
            List of project dicts with fields like slug, title, description,
            githubUrl, owner, repo, tags, envSlugs, githubData.

        Raises:
            ProjectServiceRequestError: If the API request fails.
        """
        params: dict[str, Any] = {}
        if search:
            params["search"] = search
        if featured is not None:
            params["featured"] = "true" if featured else "false"
        if category:
            params["category"] = category
        if visibility:
            params["visibility"] = visibility

        try:
            response = self.session.get("/hub-projects", params=params).json()
            data = _extract_data(response)
            if isinstance(data, list):
                return data
            if isinstance(data, dict) and "projects" in data:
                return data["projects"]
            return []
        except RequestsApiError as err:
            raise ProjectServiceRequestError(f"Failed to list hub projects: {err}") from err

    def get_project(self, slug: str) -> dict[str, Any]:
        """Get a single project by slug.

        Args:
            slug: The project slug identifier.

        Returns:
            Project dict with all metadata.

        Raises:
            ProjectNotFoundError: If the project does not exist.
            ProjectServiceRequestError: If the API request fails.
        """
        try:
            response = self.session.get(f"/hub-projects/{slug}").json()
            data = _extract_data(response)
            if not data:
                raise ProjectNotFoundError(f"Project '{slug}' not found")
            return data
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise ProjectNotFoundError(f"Project '{slug}' not found") from err
            raise ProjectServiceRequestError(f"Failed to fetch project '{slug}': {err}") from err

    def clone_project(
        self,
        github_url: str,
        target_dir: Optional[str] = None,
        progress_callback: Optional[Callable[[str, int, str], None]] = None,
        github_token: Optional[str] = None,
    ) -> Path:
        """Clone a GitHub repository to the local filesystem.

        Args:
            github_url: Full GitHub repo URL (e.g. https://github.com/user/repo)
            target_dir: Parent directory for the clone (defaults to ~/).
                The repo is cloned into ``{target_dir}/{repo_name}``.
            progress_callback: Optional ``callback(step, percent, message)``.
            github_token: Optional GitHub token for private repos. Injected
                into the clone URL as ``https://x-access-token:{token}@...``.

        Returns:
            Path to the cloned repository directory.

        Raises:
            ProjectCloneError: If the clone fails.
        """
        if target_dir is None:
            target_dir = str(Path.home())
        target = Path(target_dir).expanduser().resolve()
        target.mkdir(parents=True, exist_ok=True)

        repo_name = github_url.rstrip("/").split("/")[-1].replace(".git", "")
        clone_path = target / repo_name

        if progress_callback:
            progress_callback("clone", 0, f"Cloning {repo_name}...")

        if clone_path.exists():
            if progress_callback:
                progress_callback("clone", 100, f"{repo_name} already exists at {clone_path}")
            return clone_path

        # For private repos, inject the token into the clone URL
        clone_url = github_url
        if github_token and clone_url.startswith("https://"):
            # https://github.com/user/repo → https://x-access-token:{token}@github.com/user/repo
            clone_url = clone_url.replace("https://", f"https://x-access-token:{github_token}@", 1)

        try:
            result = subprocess.run(
                ["git", "clone", clone_url, str(clone_path)],
                capture_output=True,
                text=True,
                timeout=300,
                check=False,
            )
            if result.returncode != 0:
                stderr = result.stderr.strip() or "unknown error"
                # Sanitize token from error messages
                if github_token and github_token in stderr:
                    stderr = stderr.replace(github_token, "***")
                # An anonymous clone of a private repo fails with stderr
                # containing "Authentication failed", "could not read
                # Username", or "Repository not found" (GitHub returns 404
                # on unauthenticated reads of private repos so it can't
                # leak the repo's existence). Treat all of these as
                # "needs auth or repo doesn't exist".
                stderr_lower = stderr.lower()
                auth_or_missing = (
                    "authentication failed" in stderr_lower
                    or "could not read" in stderr_lower
                    or "repository not found" in stderr_lower
                    or "permission denied" in stderr_lower
                )
                if auth_or_missing:
                    hint = (
                        "If this repository is private, the project owner can "
                        "set a `gitReadToken` on the project, or connect your "
                        "personal GitHub account in the Vault, or export a "
                        "`GITHUB_TOKEN` in the terminal."
                    )
                    if github_token:
                        # We DID send a token and still got rejected — token
                        # is wrong or doesn't have access. Don't suggest "set
                        # a token" (one is already set).
                        hint = (
                            "The configured GitHub token does not have access "
                            "to this repository. Ask the project owner to "
                            "rotate `gitReadToken`, or connect your own "
                            "GitHub account in the Vault."
                        )
                    raise ProjectCloneError(f"Access denied cloning {repo_name}. {hint}")
                raise ProjectCloneError(f"git clone failed: {stderr}")
        except FileNotFoundError as err:
            raise ProjectCloneError("git not found in PATH") from err
        except subprocess.TimeoutExpired as err:
            raise ProjectCloneError("git clone timed out after 5 minutes") from err

        if progress_callback:
            progress_callback("clone", 100, f"Cloned {repo_name} to {clone_path}")

        return clone_path

    def _resolve_github_token(self, project: dict[str, Any]) -> Optional[str]:
        """Resolve the GitHub token to use for cloning, if any is available.

        The hub-project's ``visibility`` field is **not** consulted here — that
        flag is a UI/UX listing-scope concern (global Hub vs. org-scoped), not
        an access-control signal for the underlying GitHub repo. A project
        can perfectly well be ``visibility: 'private'`` (hidden from the
        global Hub, visible only to its org's members) and point at a fully
        public GitHub repo — that combination is valid and must clone
        anonymously.

        Token sources, in priority order:
          1. ``gitReadToken`` on the project doc — owner-provided, used when
             the GitHub repo is genuinely private (partner challenges, course
             solutions, etc.). The project owner sets this at create time.
          2. User's connected GitHub token from the Vault / connected accounts.
          3. ``GITHUB_TOKEN`` environment variable (e.g. exported in the
             user's terminal).

        Returns:
            Token string, or ``None`` if no token is available. ``None`` is a
            valid return value: the clone path will attempt an anonymous
            clone, which works for public repos. If the underlying repo is
            in fact private, the clone subprocess will fail and
            :meth:`clone_project` raises a :class:`ProjectCloneError` with a
            helpful message pointing the user at the Vault.
        """
        # 1. Project-level token (owner-provided for genuinely private repos)
        project_token = project.get("gitReadToken")
        if project_token:
            return project_token

        # 2. User's connected GitHub token (via vault / connected accounts)
        try:
            response = self.session.get("/integrations/github/token").json()
            data = response.get("data", response) if isinstance(response, dict) else {}
            user_token = data.get("accessToken") or data.get("token")
            if user_token:
                return user_token
        except Exception:  # noqa: BLE001
            pass

        # 3. GITHUB_TOKEN env var (e.g. set in terminal)
        env_token = os.environ.get("GITHUB_TOKEN")
        if env_token:
            return env_token

        # No token available. Fall through and let `git clone` attempt
        # anonymous — which succeeds for public repos. If the repo is
        # genuinely private, `clone_project` surfaces a helpful error
        # naming the Vault and `GITHUB_TOKEN` as remediation paths.
        return None

    def install_project(
        self,
        slug: str,
        target_dir: Optional[str] = None,
        install_envs: bool = True,
        progress_callback: Optional[Callable[[str, int, str], None]] = None,
    ) -> dict[str, Any]:
        """Install a hub project: clone its GitHub repo and install env(s).

        This is the main one-shot install method that:
          1. Fetches the project metadata via the API
          2. Resolves a GitHub token for private repos
          3. Clones the GitHub repository
          4. Installs all associated environments (if any)

        Args:
            slug: The project slug.
            target_dir: Directory to clone into (defaults to ~/).
            install_envs: If True, install all envSlugs from the project.
            progress_callback: ``callback(step, percent, message)`` where
                ``step`` is one of ``'project'``, ``'clone'``, ``'env'``.

        Returns:
            Dict with: project, clone_path, envs_installed, env_errors.

        Raises:
            ProjectNotFoundError: If the project doesn't exist.
            ProjectInstallError: If the install fails at any stage.
        """
        # 1. Fetch project metadata
        if progress_callback:
            progress_callback("project", 0, f"Fetching project '{slug}'...")
        project = self.get_project(slug)
        if progress_callback:
            progress_callback("project", 100, f"Loaded project '{project.get('title', slug)}'")

        github_url = project.get("githubUrl")
        if not github_url:
            raise ProjectInstallError(f"Project '{slug}' has no githubUrl")

        # 2. Resolve token for private repos
        github_token = self._resolve_github_token(project)

        # 3. Clone the repo
        try:
            clone_path = self.clone_project(
                github_url,
                target_dir=target_dir,
                progress_callback=progress_callback,
                github_token=github_token,
            )
        except ProjectCloneError as err:
            raise ProjectInstallError(f"Clone failed: {err}") from err

        # 3. Install environments (if any)
        envs_installed: list[str] = []
        env_errors: list[dict[str, str]] = []
        env_slugs = project.get("envSlugs") or []

        if install_envs and env_slugs:
            try:
                from qbraid_core.services.environments import EnvironmentManagerClient
            except ImportError:
                env_errors.append(
                    {
                        "slug": "*",
                        "error": "qbraid_core.services.environments not available",
                    }
                )
            else:
                emc = EnvironmentManagerClient(session=self.session)
                envs_target = str(Path.home() / ".qbraid" / "environments")

                total = len(env_slugs)
                for i, env_slug in enumerate(env_slugs):
                    base_pct = int((i / total) * 100)

                    def env_progress(
                        stage: str,
                        completed: int,
                        total_bytes: int,
                        _idx=i,
                        _base=base_pct,
                        _slug=env_slug,
                    ):
                        if progress_callback:
                            inner_pct = int((completed / total_bytes) * 100) if total_bytes else 0
                            overall = _base + int(inner_pct / total)
                            progress_callback(
                                "env",
                                overall,
                                f"Installing {_slug} ({stage})",
                            )

                    if progress_callback:
                        progress_callback(
                            "env", base_pct, f"Installing {env_slug} ({i + 1}/{total})..."
                        )
                    try:
                        preflight, env_info = _run_env_preflight(emc, env_slug, progress_callback)
                        _install_env_with_preflight(
                            emc,
                            env_slug,
                            envs_target,
                            preflight,
                            env_info,
                            env_progress,
                        )
                        envs_installed.append(env_slug)
                    except Exception as err:  # noqa: BLE001
                        logger.warning("Failed to install env %s: %s", env_slug, err)
                        env_errors.append({"slug": env_slug, "error": str(err)})

        if progress_callback:
            progress_callback("done", 100, "Project installed")

        return {
            "project": project,
            "clone_path": str(clone_path),
            "envs_installed": envs_installed,
            "env_errors": env_errors,
        }

    async def install_project_async(
        self,
        slug: str,
        target_dir: Optional[str] = None,
        install_envs: bool = True,
        progress_callback: Optional[Callable[[str, int, str], None]] = None,
    ) -> dict[str, Any]:
        """Async version of install_project for use inside an event loop.

        Same args/returns as ``install_project``. Use this from inside
        Tornado/asyncio handlers; ``install_project`` is for CLI/sync code.
        """
        import asyncio

        # 1. Fetch project (sync — fast)
        if progress_callback:
            progress_callback("project", 0, f"Fetching project '{slug}'...")
        project = await asyncio.to_thread(self.get_project, slug)
        if progress_callback:
            progress_callback("project", 100, f"Loaded project '{project.get('title', slug)}'")

        github_url = project.get("githubUrl")
        if not github_url:
            raise ProjectInstallError(f"Project '{slug}' has no githubUrl")

        # 2. Resolve token for private repos
        github_token = await asyncio.to_thread(self._resolve_github_token, project)

        # 3. Clone (sync subprocess in thread)
        try:
            clone_path = await asyncio.to_thread(
                self.clone_project, github_url, target_dir, progress_callback, github_token
            )
        except ProjectCloneError as err:
            raise ProjectInstallError(f"Clone failed: {err}") from err

        # 4. Install environments
        envs_installed: list[str] = []
        env_errors: list[dict[str, str]] = []
        env_slugs = project.get("envSlugs") or []

        if install_envs and env_slugs:
            try:
                from qbraid_core.services.environments import EnvironmentManagerClient
            except ImportError:
                env_errors.append(
                    {
                        "slug": "*",
                        "error": "qbraid_core.services.environments not available",
                    }
                )
            else:
                emc = EnvironmentManagerClient(session=self.session)
                envs_target = str(Path.home() / ".qbraid" / "environments")

                total = len(env_slugs)
                for i, env_slug in enumerate(env_slugs):
                    base_pct = int((i / total) * 100)

                    def env_progress(
                        stage: str,
                        completed: int,
                        total_bytes: int,
                        _idx=i,
                        _base=base_pct,
                        _slug=env_slug,
                    ):
                        if progress_callback:
                            inner_pct = int((completed / total_bytes) * 100) if total_bytes else 0
                            overall = _base + int(inner_pct / total)
                            progress_callback(
                                "env",
                                overall,
                                f"Installing {_slug} ({stage})",
                            )

                    if progress_callback:
                        progress_callback(
                            "env",
                            base_pct,
                            f"Installing {env_slug} ({i + 1}/{total})...",
                        )

                    try:
                        preflight, env_info = await asyncio.to_thread(
                            _run_env_preflight, emc, env_slug, progress_callback
                        )
                        await _install_env_with_preflight_async(
                            emc,
                            env_slug,
                            envs_target,
                            preflight,
                            env_info,
                            env_progress,
                        )
                        envs_installed.append(env_slug)
                    except Exception as err:  # noqa: BLE001
                        logger.warning("Failed to install env %s: %s", env_slug, err)
                        env_errors.append({"slug": env_slug, "error": str(err)})

        if progress_callback:
            progress_callback("done", 100, "Project installed")

        return {
            "project": project,
            "clone_path": str(clone_path),
            "envs_installed": envs_installed,
            "env_errors": env_errors,
        }
